public class CavePatrol {
    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        StringTokenizer st = new StringTokenizer(br.readLine());

        int n = Integer.parseInt(st.nextToken()); // number of cells
        int H = Integer.parseInt(st.nextToken()); // initial and max hit points

        int[] cells = new int[n];
        st = new StringTokenizer(br.readLine());
        for (int i = 0; i < n; i++) {
            cells[i] = Integer.parseInt(st.nextToken());
        }

        int currentHP = H;
        int maxHP = H;

        for (int i = 0; i < n; i++) {
            int val = cells[i];

            if (val > 0) {
                // Potion: restore HP but cannot exceed maxHP
                currentHP = Math.min(maxHP, currentHP + val);
            } else if (val < 0) {
                // Trap: lose HP
                currentHP += val; // val is negative
                if (currentHP <= 0) {
                    System.out.println("No");
                    return;
                }
            }
            // val == 0 means empty cell, do nothing
        }

        System.out.println("Yes");
    }
}

